<template><main class="staff-training-page staff-ui"><header class="staff-page-heading"><div><span class="staff-eyebrow">粤宏潮 · 人员与组织</span><h1>实习店长与培训派发</h1><p>所属门店承担全部工资；培训门店负责带教和当班，不办理结训审批。</p></div><el-button @click="load" :loading="busy">刷新</el-button></header><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="training-panel"><el-select v-model="employeeId" filterable placeholder="选择实习店长" style="width:min(360px,100%)" @change="selectEmployee"><el-option v-for="e in data.employees" :key="e.id" :value="e.id" :label="e.name+' · '+e.home_store_name"/></el-select><el-empty v-if="!data.employees.length" description="暂无可管理或查看的实习店长，请先核对员工归属和岗位授权"/><template v-if="employee"><div class="relation-grid"><div><small>人员所属</small><b>{{employee.home_store_name||'待确认'}}</b></div><div><small>工资承担</small><b>{{employee.payroll_store_name||'待确认'}}</b></div><div><small>当前工作地点</small><b>{{employee.work_store_name||'待确认'}}</b></div><div><small>直属督导</small><b>{{employee.supervisor_name}}</b></div></div><el-alert v-if="employee.needs_review" title="已超过预计培训结束日期，请直属督导确认续期或归回；系统不会自动判定合格。" type="warning" :closable="false"/><el-collapse><el-collapse-item v-if="employee.can_configure" title="所属门店与直属督导设置" name="setup"><el-form label-position="top"><div class="two"><el-form-item label="所属门店（允许筹建门店）"><el-select v-model="setup.home_store_id" filterable><el-option v-for="s in data.stores" :key="s.id" :value="s.id" :label="s.store_name"/></el-select></el-form-item><el-form-item label="直属督导"><el-select v-model="setup.supervisor_user_id" filterable><el-option v-for="p in data.supervisors" :key="p.id" :value="p.id" :label="p.name"/></el-select></el-form-item></div><p class="muted">若列表没有对应督导，请先在集团岗位权限中开通“培训派发、续期与归回”，并配置其负责的所属门店。</p><el-form-item label="设置原因"><el-input v-model="setup.reason" maxlength="1000" type="textarea"/></el-form-item><p class="muted">保存将任职登记为实习店长，账号普通任务与学习归属设为A店；培训期间临时开放培训店任务。正式调店和店长任命仍走对应流程。</p><el-button type="primary" :loading="busy" @click="saveSetup" :disabled="!setup.reason.trim()||!setup.supervisor_user_id">保存设置</el-button></el-form></el-collapse-item><el-collapse-item v-if="employee.can_manage&&employee.supervisor_user_id" title="安排外派培训" name="start"><el-form label-position="top"><div class="two"><el-form-item label="培训门店"><el-select v-model="form.training_store_id" filterable @change="loadMentors"><el-option v-for="s in trainingStores" :key="s.id" :value="s.id" :label="s.store_name"/></el-select></el-form-item><el-form-item label="带教店长"><el-select v-model="form.mentor_user_id" filterable><el-option v-for="p in mentors" :key="p.id" :value="p.id" :label="p.name"/></el-select></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="form.start_date" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="预计结束日期"><el-date-picker v-model="form.expected_end_date" type="date" value-format="YYYY-MM-DD"/></el-form-item></div><el-form-item label="培训安排说明"><el-input v-model="form.reason" type="textarea" maxlength="1000"/></el-form-item><el-button type="primary" :loading="busy" :disabled="!form.reason.trim()||!form.training_store_id||!form.mentor_user_id||!form.expected_end_date" @click="start">确认派发</el-button></el-form></el-collapse-item></el-collapse></template></section><section class="training-panel"><h2>培训记录</h2><el-table :data="filteredRecords" stripe><el-table-column prop="name" label="员工" min-width="100"/><el-table-column prop="home_store_name" label="所属／工资门店" min-width="170"/><el-table-column prop="training_store_name" label="培训门店" min-width="170"/><el-table-column prop="mentor_name" label="带教店长" width="110"/><el-table-column label="培训日期" min-width="205"><template #default="{row}">{{row.start_date}} 至预计 {{row.expected_end_date}}<p v-if="row.return_date">归回生效：{{row.return_date}}</p></template></el-table-column><el-table-column prop="state" label="状态" width="110"/><el-table-column label="操作" width="230"><template #default="{row}"><el-button link @click="openAttendance(row)">培训打卡</el-button><el-button link @click="detail=row">查看记录</el-button><el-button v-if="row.can_manage" type="primary" link @click="openAction(row)">续期／归回</el-button></template></el-table-column></el-table></section><el-drawer :model-value="!!attendanceRecord" title="培训期间打卡" size="520px" @close="attendanceRecord=null"><p class="muted">只显示培训期间的实际打卡；培训安排不等同于钉钉外出已审批或已切换地点。</p><el-date-picker v-model="attendanceRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期"/><el-button @click="loadAttendance">查询</el-button><el-table :data="attendanceRows"><el-table-column prop="date" label="日期" width="110"/><el-table-column label="打卡记录" min-width="160"><template #default="{row}"><p v-for="(p,i) in row.punches" :key="i">{{p.time}} · {{p.type}}</p><span v-if="!row.punches.length">{{row.status}}</span></template></el-table-column></el-table></el-drawer><el-drawer v-model="actionVisible" title="培训调整" size="420px"><el-form label-position="top"><el-form-item label="操作"><el-radio-group v-model="action.action"><el-radio-button value="extend">延长培训</el-radio-button><el-radio-button value="return">结束并归回</el-radio-button><el-radio-button v-if="selected?.start_date>today" value="cancel">取消未开始安排</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="action.action!=='cancel'" :label="action.action==='extend'?'新预计结束日期':'归回生效日期（当日开始回所属门店）'"><el-date-picker v-model="action.date" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="调整原因"><el-input v-model="action.reason" type="textarea" maxlength="1000"/></el-form-item><el-button type="primary" :loading="busy" :disabled="!action.reason.trim()||action.action!=='cancel'&&!action.date" @click="saveAction">确认调整</el-button></el-form></el-drawer><el-drawer :model-value="!!detail" title="培训记录与变更历史" @close="detail=null"><template v-if="detail"><h3>{{detail.name}} · {{detail.state}}</h3><p>{{detail.home_store_name}} → {{detail.training_store_name}}</p><p>工资始终由{{detail.home_store_name}}承担</p><el-timeline><el-timeline-item v-for="e in detail.events" :key="e.created_at+e.action" :timestamp="e.created_at"><b>{{e.action}} · {{e.actor_name}}</b><p>{{e.reason}}</p></el-timeline-item></el-timeline></template></el-drawer></main></template>
<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {staffTrainingApi as api} from '@/api'
import '@/styles/staff-workspace.css'
const today=new Date(Date.now()+28800000).toISOString().slice(0,10),data=ref({employees:[],stores:[],supervisors:[]}),records=ref([]),employeeId=ref(null),busy=ref(false),error=ref(''),mentors=ref([]),selected=ref(null),detail=ref(null),actionVisible=ref(false)
const attendanceRecord=ref(null),attendanceRange=ref([]),attendanceRows=ref([])
const setup=reactive({home_store_id:null,supervisor_user_id:null,reason:'',version:0}),form=reactive({training_store_id:null,mentor_user_id:null,start_date:today,expected_end_date:'',reason:''}),action=reactive({action:'extend',date:'',reason:''})
const employee=computed(()=>data.value.employees.find(e=>e.id===employeeId.value)),trainingStores=computed(()=>data.value.stores.filter(s=>s.id!==employee.value?.home_store_id&&!/闭店|停业|筹建|迁址/.test(s.status||''))),filteredRecords=computed(()=>records.value.filter(r=>!employeeId.value||r.employee_id===employeeId.value))
function selectEmployee(){const e=employee.value;Object.assign(setup,{home_store_id:e?.home_store_id||null,supervisor_user_id:e?.supervisor_user_id||null,reason:'',version:e?.supervisor_version||0});Object.assign(form,{training_store_id:null,mentor_user_id:null,start_date:today,expected_end_date:'',reason:''});mentors.value=[]}
async function load(){try{const [o,r]=await Promise.all([api.options(),api.list()]);data.value=o;records.value=r.rows;if(!o.employees.some(e=>e.id===employeeId.value))employeeId.value=null;selectEmployee();error.value=''}catch(e){error.value=e.message}}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn();await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function loadMentors(){form.mentor_user_id=null;try{mentors.value=(await api.mentors(form.training_store_id)).people}catch(e){error.value=e.message}}
function saveSetup(){run(()=>api.setup(employeeId.value,{...setup}))}
function start(){run(()=>api.start({...form,employee_id:employeeId.value}))}
function openAction(r){selected.value=r;Object.assign(action,{action:'extend',date:'',reason:''});actionVisible.value=true}
function saveAction(){run(async()=>{await api.change(selected.value.id,{action:action.action,expected_end_date:action.date,return_date:action.date,reason:action.reason,revision:selected.value.revision});actionVisible.value=false})}
function openAttendance(r){attendanceRecord.value=r;const end=r.return_date?new Date(Date.parse(r.return_date+'T00:00:00Z')-86400000).toISOString().slice(0,10):today;const last=end<today?end:today;const monthStart=new Date(Date.parse(last+'T00:00:00Z')-30*86400000).toISOString().slice(0,10);attendanceRange.value=[r.start_date>monthStart?r.start_date:monthStart,last];loadAttendance()}
async function loadAttendance(){attendanceRows.value=[];if(!attendanceRange.value?.length||attendanceRange.value[0]>attendanceRange.value[1])return;try{attendanceRows.value=(await api.attendance(attendanceRecord.value.id,{from:attendanceRange.value[0],to:attendanceRange.value[1]})).rows}catch(e){error.value=e.message}}
onMounted(load)
</script>
<style scoped>.staff-training-page{padding:24px;max-width:1500px;margin:auto}.training-panel{background:var(--el-bg-color);border:1px solid var(--el-border-color-light);border-radius:12px;padding:22px;margin-top:20px}.training-panel h2{font-size:17px;margin:0 0 18px}.relation-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.relation-grid>div{padding:16px;background:var(--el-fill-color-light);border-radius:10px}.relation-grid small{display:block;color:var(--el-text-color-secondary);margin-bottom:10px}.relation-grid b{font-size:15px;line-height:1.7}.two{display:grid;grid-template-columns:1fr 1fr;gap:0 20px;max-width:850px}.two .el-select{width:100%}.muted{font-size:12px;line-height:1.8;color:var(--el-text-color-secondary)}@media(max-width:700px){.staff-training-page{padding:16px}.relation-grid,.two{grid-template-columns:1fr 1fr}}@media(max-width:420px){.two{grid-template-columns:1fr}}</style>
